contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function performing the minimal sequence: two deposits by this contract
    function runTest(uint firstAmt, uint secondAmt) public payable {
        // require this contract has enough ETH to send the two deposits
        require(address(this).balance >= firstAmt + secondAmt);

        // first deposit into C from this contract
        c.Deposit{value: firstAmt}();

        // second deposit into C from this contract
        c.Deposit{value: secondAmt}();

        // read the recorded balance for this contract's address
        uint bal = c.balances(address(this));

        // property: after the second deposit, recorded balance must be >= the second (last) deposit
        assert(bal >= secondAmt);
    }

    // allow contract to receive ETH so tests can fund it
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // deposit1 and deposit2 are amounts sent with the two Deposit calls
    function run(uint deposit1, uint deposit2) public payable {
        // ensure this tester has enough balance to send both deposits
        require(address(this).balance >= deposit1 + deposit2, "insufficient test balance");
        // first deposit
        c.Deposit{value: deposit1}();
        // second deposit
        c.Deposit{value: deposit2}();
        // after two deposits from this test contract, the recorded balance (getter balances) must equal the sum
        // use the public balances getter: c.balances(address)
        assert(c.balances(address(this)) == deposit1 + deposit2);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function: deposit once and check recorded balance increased exactly by amt
    function run(address depositor, uint256 amt) public payable {
        // ensure this contract has enough ETH to forward
        require(address(this).balance >= amt, "insufficient balance for test");
        // record prior balance from contract's public getter
        uint256 before = c.balances(depositor);
        // perform deposit on behalf of this contract's msg.sender; need to send ETH from this contract
        // we use call on C.Receive by invoking Deposit payable
        // perform the deposit by calling c.Deposit() and sending amt
        // but Deposit credits msg.sender, so we must have depositor be this contract; test requires depositor == address(this)
        require(depositor == address(this), "depositor must be this contract for Deposit to credit correctly");

        c.Deposit{value: amt}();

        uint256 after = c.balances(depositor);
        // The property: after - before == amt
        assert(after - before == amt);
    }

    // allow this contract to receive ETH so the test runner can fund it
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        uint before = address(c).balance;
        c.Deposit{value: amount}();
        uint afterBal = address(c).balance;
        assert(afterBal == before + amount);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // depositAmount: amount of wei to send with Deposit
    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);

        // perform the deposit on behalf of this contract caller (msg.sender of run)
        c.Deposit{value: depositAmount}();

        // read the recorded balance for this contract (the caller of Deposit)
        uint recorded = c.balances(address(this));

        // For the original contract, a single Deposit of v should make the recorded balance exactly v.
        // The mutant double-adds msg.value, so recorded would be 2*v and this assertion will fail on the mutant.
        assert(recorded == depositAmount);
    }

    receive() external payable {}
}
